function buildExtraDictionaries(base){for(const [lang,raw] of Object.entries(uiTranslations)){const values=raw.split('|');if(values.length!==uiKeys.length)throw Error(`UI translation count ${lang}: ${values.length}/${uiKeys.length}`);base[lang]={...base.en,...Object.fromEntries(uiKeys.map((key,i)=>[key,values[i]]))}}}

buildExtraDictionaries(dictionaries);
for(const [lang,extra] of Object.entries(window.DHI18n.extra))Object.assign(dictionaries[lang],extra);
for(const words of Object.values(dictionaries))words.app='SiteCam';
const keys=['logo','project','area','work','contractor','supervisor','note','date','weather','place','coordinates','altitude','heading','gpsAccuracy','unit','owner','supervisionUnit','inspectionUnit','count','deadline','speed','duration','signature','qr'];const defaultOn=['logo','project','area','supervisor','date'];const colors=['#236bd7','#20baba','#05ae2a','#ff8c09','#d70018','#9711ae','#293849'];const defaults={planRegistry:[],planPins:[],planActive:{},planPinStyle:{shape:'severity',size:24,opacity:90,criticalShape:'triangle'},marker:{enabled:false,text:'1',size:80,color:'#ff7a00',mode:'solid'},projects:Array.from({length:10},(_,i)=>({name:`Công trình ${String(i+1).padStart(2,'0')}`,folderUrl:''})),currentProject:0,lang:'vi',mode:'transparent',scale:100,width:68,opacity:80,color:colors[0],values:{project:'DONG HUI',count:'1'},enabled:Object.fromEntries(keys.map(k=>[k,defaultOn.includes(k)])),custom:[],zoom:1,brightness:100,shutterSound:true,photoQuality:'medium'};let state=structuredClone(defaults),logoImage=null,stream=null,source=null,shotAt=null,shotCount=null,facing='environment',activeCameraFacing='environment',focusPoint={x:.5,y:.5},torchOn=false,paintLoop=0,stampBounds=null,markerBounds=null,previewRect=null,lastPhoto=null,sourceRatio=null,liveRotation=0,sourceRotation=null,stampLocalBounds=null,markerLocalBounds=null;let logoData='data:image/png;base64,';const video=$('video'),photo=$('photo');const tr=k=>dictionaries[state.lang]?.[k]||dictionaries.en[k]||k;
try{const saved=JSON.parse(localStorage.getItem('dh_stamp_v2')||'null');if(saved){state={...defaults,...saved,values:{...defaults.values,...saved.values},enabled:{...defaults.enabled,...saved.enabled},marker:{...defaults.marker,...saved.marker},planRegistry:Array.isArray(saved.planRegistry)?saved.planRegistry:[],planPins:Array.isArray(saved.planPins)?saved.planPins:[],planActive:saved.planActive&&typeof saved.planActive==='object'?saved.planActive:{},custom:Array.isArray(saved.custom)?saved.custom:[],projects:Array.isArray(saved.projects)&&saved.projects.length>=10?saved.projects:defaults.projects};logoData=saved.logoData||''}else{state.values.area='Ch\u01b0a nh\u1eadp';state.values.supervisor='Ch\u01b0a nh\u1eadp'}}catch(_){}function status(k,error=false){let el=$('status');el.textContent=tr(k);el.className='status'+(error?' error':'');el.style.display='block'}function clean(x,n=150){return String(x??'').replace(/[\r\n\t]+/g,' ').trim().slice(0,n)}function persist(){try{localStorage.setItem('dh_stamp_v2',JSON.stringify({...state,logoData}))}catch(_){}renderStamp();renderPreview()}function nowText(){const d=shotAt||new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}.${p(d.getMonth()+1)}.${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`}function number(){return Math.max(1,Math.min(999999,parseInt(state.values.count,10)||1))}function stampNumber(){return window.fieldPlan?.activePin?.code??shotCount??number()}
function fieldRow(k,customIndex=null){const row=document.createElement('div');row.className='field';const check=document.createElement('input');check.type='checkbox';check.className='toggle';check.checked=customIndex===null?!!state.enabled[k]:!!state.custom[customIndex].enabled;check.setAttribute('aria-label',tr(k));check.onchange=()=>{if(customIndex===null)state.enabled[k]=check.checked;else state.custom[customIndex].enabled=check.checked;row.classList.toggle('disabled',!check.checked);persist()};row.append(check);const label=document.createElement('label');const span=document.createElement('span');span.textContent=tr(k);label.append(span);if(k!=='logo'&&k!=='date'){let input=document.createElement('input');input.type=k==='count'?'number':k==='deadline'?'datetime-local':'text';input.placeholder=tr('value');input.maxLength=150;input.value=customIndex===null?(state.values[k]||''):(state.custom[customIndex].value||'');if(k==='count'){input.min='1';input.max='999999'}input.oninput=()=>{if(customIndex===null){state.values[k]=input.value;if(k==='count'&&source)shotCount=number()}else state.custom[customIndex].value=input.value;persist()};label.append(input)}if(customIndex!==null){const name=document.createElement('input');name.value=state.custom[customIndex].name||'';name.placeholder=tr('custom');name.maxLength=35;name.oninput=()=>{state.custom[customIndex].name=name.value;persist()};label.prepend(name);span.remove()}row.append(label);if(k==='logo'){const img=document.createElement('span');img.textContent=logoData?'✓':'›';row.append(img)}if(customIndex!==null){const del=document.createElement('button');del.type='button';del.textContent='×';del.style.cssText='border:0;background:#fff;color:#b22;font-size:23px';del.onclick=()=>{state.custom.splice(customIndex,1);persist();renderFields()};row.append(del)}row.classList.toggle('disabled',!check.checked);return row}
function renderFields(){const root=$('fields');root.replaceChildren();for(const k of keys)root.append(fieldRow(k));state.custom.forEach((_,i)=>root.append(fieldRow('custom',i)))}function renderSites(){const select=$('siteSelect'),root=$('sitesList');select.replaceChildren();root.replaceChildren();state.projects.forEach((site,i)=>{const opt=document.createElement('option');opt.value=String(i);opt.textContent=/^Công trình \d{2}$/.test(site.name||'')?`${tr('currentSite')} ${String(i+1).padStart(2,'0')}`:clean(site.name,60)||`${tr('currentSite')} ${i+1}`;select.append(opt);const row=document.createElement('div');row.className='site-row';const title=document.createElement('strong');title.textContent=`${tr('currentSite')} ${i+1}`;row.append(title);const name=document.createElement('input');name.value=site.name||'';name.placeholder=tr('currentSite');name.maxLength=60;name.onchange=()=>{site.name=clean(name.value,60);if(i===Number(state.currentProject))state.values.project=site.name;persist();renderSites();renderFields()};row.append(name);const folder=document.createElement('input');folder.value=site.folderUrl||'';folder.type='url';folder.placeholder=tr('folderLink');folder.onchange=()=>{site.folderUrl=folder.value.trim();site.driveEnabled=false;site.driveFolderVerified=null;if(i===Number(state.currentProject))$('driveLink').value=site.folderUrl;persist();window.fieldDrive?.refresh()};row.append(folder);root.append(row)});select.value=String(Math.max(0,Math.min(state.projects.length-1,Number(state.currentProject)||0)));$('driveLink').value=state.projects[Number(select.value)]?.folderUrl||'';window.fieldDrive?.refresh()}
$('siteSelect').onchange=()=>{state.currentProject=Number($('siteSelect').value);state.values.project=state.projects[state.currentProject].name;window.fieldPlan?.projectChanged();$('driveLink').value=state.projects[state.currentProject].folderUrl||'';persist();renderFields()};$('editSites').onclick=()=>{openEditor();$('sitesList').scrollIntoView({block:'start'})};$('driveLink').oninput=()=>{state.projects[state.currentProject].folderUrl=$('driveLink').value.trim();try{localStorage.setItem('dh_stamp_v2',JSON.stringify({...state,logoData}))}catch(_){}};
function driveFolderUrl(){const value=$('driveLink').value.trim();if(!value){status('driveMissing',true);return null}try{const url=new URL(value);if(url.protocol!=='https:'||url.hostname!=='drive.google.com'||!(url.pathname.includes('/folders/')||(url.pathname==='/open'&&url.searchParams.has('id'))))throw Error('folder');return url.href}catch(_){status('driveInvalid',true);return null}}
$('openDrive').onclick=()=>{const link=driveFolderUrl();if(!link)return;window.open(link,'_blank','noopener,noreferrer')};
$('chooseUpload').onclick=()=>{if(!driveFolderUrl())return;$('uploadPicker').click()};
